insert into public.studios (id, name, description, long_description, location, image_url, hourly_rate, unavailable_slots, sort_order) values
    ('studio-a', 'The Warmth Room', 'The Vintage Analog Studio', 'This studio is filled with warm wood tones, a classic mixing console with numerous knobs and faders, reel-to-reel tape machines, and vintage synthesizers. There''s a cozy, slightly cluttered feel, perfect for capturing authentic, old-school sounds.', 'First Floor, Main Building', 'images/studio-a.jpg', 250, '{}'::jsonb, 0),
    ('studio-b', 'Pure Signal Studio', 'The Modern Minimalist Studio', 'Sleek, clean lines dominate this space. White walls, a single large computer monitor, a compact MIDI controller, and strategically placed acoustic panels create an uncluttered, high-tech environment optimized for digital production.', 'First Floor, West Wing', 'images/studio-b.jpg', 200, '{}'::jsonb, 1),
    ('studio-c', 'Raw Tracks Studio', 'The Live Band Jam Room Studio', 'This space is set up for collaborative live recording. It features a drum kit, several guitar amps, microphones on stands, and soundproofing on the walls, giving it a raw, energetic feel ready for a band to lay down tracks.', 'Second Floor, Main Building', 'images/studio-c.jpg', 300, '{}'::jsonb, 2),
    ('studio-d', 'The Drifting Note', 'The Ambient Chillout Studio', 'Soft, indirect lighting, comfortable seating, plants, and a variety of unique instruments like kalimbas, hand drums, and a modular synthesizer create a tranquil and inspiring atmosphere for experimental or meditative music creation.', 'Second Floor, East Wing', 'images/studio-d.jpg', 180, '{}'::jsonb, 3),
    ('studio-e', 'City Beat Studios', 'The Urban Loft Producer Studio', 'This studio is situated in a stylish city loft with large windows overlooking the urban landscape. It combines professional gear with a comfortable, lived-in feel – a powerful computer setup, studio monitors, a large keyboard, and perhaps some art or personal touches on the walls, reflecting a blend of work and lifestyle.', 'Third Floor, Control Room', 'images/studio-e.jpg', 220, '{}'::jsonb, 4)
insert into public.instruments (id, name, image_url, description, long_description, fun_fact, joke, sort_order) overriding system value values
    (1, 'Violin', 'images/violin.jpg', 'A versatile string instrument with a warm, rich tone.', 'The violin, often considered the ''prima donna'' of the orchestra, boasts a vocal-like quality that can soar with passion or whisper with tenderness. Its four strings are typically tuned in perfect fifths, producing a truly captivating sound whether played solo or within a grand symphony.', 'Stradivarius violins, made by the Stradivari family in the 17th and 18th centuries, are considered among the finest string instruments ever made, often selling for millions of dollars.', 'Why did the violin get sent to detention? Because it was always fiddling around!', 0),
    (2, 'Guitar', 'images/guitar.jpg', 'A classic acoustic guitar with steel strings, perfect for any genre.', 'From campfire singalongs to stadium rock anthems, the guitar is arguably the most popular instrument worldwide. Its versatility allows it to be strummed, plucked, or fingerpicked, providing rhythm, melody, and harmony across countless musical styles.', 'The world''s most expensive guitar ever sold was Kurt Cobain''s 1959 Martin D-18E, which fetched a staggering $6 million at auction.', 'What do you call a guitar player without a girlfriend? Homeless.', 1),
    (3, 'Piano', 'images/piano.jpg', 'A grand piano offering a wide dynamic range and expressive sound.', 'The piano, often called the ''king of instruments'', is capable of producing a vast range of sounds, from thunderous lows to delicate highs. Its 88 keys provide a unique tactile and sonic experience, making it a cornerstone of classical, jazz, and popular music.', 'The word ''piano'' is a shortened version of ''pianoforte'', which means ''soft-loud'' in Italian, referring to the instrument''s ability to play at different volumes depending on how hard the keys are pressed.', 'What''s a piano''s favorite type of candy? A ''key'' lime pie!', 2),
    (4, 'Trumpet', 'images/trumpet.jpg', 'A brass instrument known for its bright, powerful sound.', 'The trumpet''s bright and piercing tone cuts through an ensemble, making it ideal for fanfares, jazz solos, and orchestral highlights. It''s a challenging instrument to master, requiring precise breath control and lip tension to produce its characteristic sound.', 'The earliest trumpets, dating back to 1500 BC, were used in ancient Egypt not for music, but for military signals and religious ceremonies.', 'Why did the trumpet player cross the road? To blow his own horn!', 3),
    (5, 'Drum Kit', 'images/drums.jpg', 'A full professional drum kit for powerful rhythmic foundations.', 'The drum kit is the rhythmic backbone of most modern music. Comprising various drums and cymbals, it allows a single musician to create complex rhythmic patterns that drive the energy and feel of a song. It''s all about precision, power, and groove!', 'Before the invention of the modern drum kit, multiple percussionists were needed to play all the different drums and cymbals that one drummer can now play simultaneously.', 'What''s a drummer''s favorite type of pizza? One with a good ''beat''!', 4),
    (6, 'Microphone', 'images/mic.jpg', 'Studio-grade condenser microphone for crystal-clear vocal recording.', 'While not an ''instrument'' in the traditional sense, a good microphone is essential for capturing the nuances of vocals and acoustic instruments. It''s the bridge between the sound waves in the air and the electrical signals that can be recorded and amplified.', 'The earliest successful microphone, the carbon microphone, was independently developed by David Edward Hughes in England and Emile Berliner and Thomas Edison in the US in the 1870s.', 'Why did the microphone break up with the speaker? Because they had too many ''sound'' arguments!', 5)
insert into public.testimonials (id, name, stars, text, avatar_url, sort_order) overriding system value values
    (1, 'Adi', 5, 'The team was super professional and made my first music session extremely good.', 'images/avatar-adi.jpg', 0),
    (2, 'Sunil K', 5, 'Very good sound quality and fine-tuned equipment overall!', 'images/avatar-sunil.jpg', 1),
    (3, 'Liam D', 5, 'The expertise and patience makes me highly recommend this place!', 'images/avatar-liam.jpg', 2),
    (4, 'Maria R', 5, 'Amazing facilities and very professional staff. Highly recommended!', 'images/avatar-maria.jpg', 3)
